import re

_WORD_UNITS = {
    "days": "d", "day": "d",
    "hours": "h", "hour": "h",
    "minutes": "m", "minute": "m",
    "seconds": "s", "second": "s",
}

_PATTERN = re.compile(
    r"(\d+(?:\.\d+)?)([dhms])"
)


def _normalize(text):
    """Lowercase and replace spelled-out unit words with their letters."""
    text = str(text).strip().lower()
    out = []
    for token in text.split():
        for word, letter in _WORD_UNITS.items():
            token = token.replace(word, letter)
        out.append(token)
    return "".join(out).replace(" ", "")


def parse_duration(text):
    """Parse a duration string like '1h30m' or '1 hour 30 minutes'
    and return whole seconds as an int. Raises ValueError on bad input."""
    normalized = _normalize(text)
    if not normalized:
        raise ValueError(f"invalid duration: {text!r}")
    total = 0.0
    consumed = []
    for match in _PATTERN.finditer(normalized):
        value, unit = float(match.group(1)), match.group(2)
        multiplier = {"d": 86400, "h": 3600, "m": 60, "s": 1}[unit]
        total += value * multiplier
        consumed.append(match.span())
    # reject leftover characters
    re.sub(r"(\d+(?:\.\d+)?)([dhms])", "", normalized)
    if not consumed or re.sub(r"(\d+(?:\.\d+)?)([dhms])", "", normalized):
        raise ValueError(f"invalid duration: {text!r}")
    return int(total)


def format_duration(seconds):
    """Format a number of seconds as the shortest string parse_duration accepts."""
    seconds = int(seconds)
    if seconds < 0:
        raise ValueError("cannot format negative durations")
    if seconds == 0:
        return "0s"
    parts = []
    for letter, length in (("d", 86400), ("h", 3600), ("m", 60), ("s", 1)):
        count, seconds = divmod(seconds, length)
        if count:
            parts.append(f"{count}{letter}")
    return "".join(parts)


if __name__ == "__main__":
    import sys
    tests = {
        "1h30m": 5400,
        "45s": 45,
        "1 hour 30 minutes": 5400,
        "2 days": 172800,
        "1.5h": 5400,
    }
    ok = True
    for raw, expected in tests.items():
        try:
            got = parse_duration(raw)
        except ValueError:
            ok = False
        ok = ok and got == expected
        print(raw, "->", got, "expected", expected)
    print("roundtrip:", parse_duration(format_duration(90061)) == 90061)
    sys.exit(0 if ok else 1)

